// CurrentUserResource groups the CurrentUser operations.
type CurrentUserResource struct {
	transport *runtime.Transport
}

// CreateRepo creates a repository of your own (createCurrentUserRepo).
func (r *CurrentUserResource) CreateRepo(ctx context.Context, body *CreateRepoOption) (*Repository, error) {
	return runtime.Call[*Repository](ctx, r.transport, opCreateCurrentUserRepo, runtime.Input{Body: body})
}

// DeleteToken deletes the access token you are authenticated with (deleteCurrentToken).
func (r *CurrentUserResource) DeleteToken(ctx context.Context) error {
	_, err := runtime.Call[any](ctx, r.transport, opDeleteCurrentToken, runtime.Input{})
	return err
}

// GetToken gets the access token you are authenticated with (getCurrentToken).
func (r *CurrentUserResource) GetToken(ctx context.Context) (*CurrentAccessToken, error) {
	return runtime.Call[*CurrentAccessToken](ctx, r.transport, opGetCurrentToken, runtime.Input{})
}

// GetSettings gets your user settings (getUserSettings).
func (r *CurrentUserResource) GetSettings(ctx context.Context) (*UserSettings, error) {
	return runtime.Call[*UserSettings](ctx, r.transport, opGetUserSettings, runtime.Input{})
}

// GetGPGVerificationToken gets the token to sign to verify a GPG key (getVerificationToken).
func (r *CurrentUserResource) GetGPGVerificationToken(ctx context.Context) (string, error) {
	return runtime.Call[string](ctx, r.transport, opGetVerificationToken, runtime.Input{})
}

